import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../utils/AuthContext';
import { postAPI } from '../utils/api';
import logo from '../Assets/logo.png';
import './styles/Activities.css';

export default function GamerActivitiesPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [posts, setPosts] = useState([]);
  const [newPost, setNewPost] = useState('');
  const [showPostForm, setShowPostForm] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [mediaPreview, setMediaPreview] = useState(null);

  useEffect(() => {
    loadPosts();
  }, []);

  const loadPosts = async () => {
    try {
      const response = await postAPI.getFeed();
      setPosts(response.data);
    } catch (error) {
      console.error('Failed to load posts:', error);
    }
  };

  const handleCreatePost = async () => {
    try {
      await postAPI.create({
        content: newPost,
        post_type: 'general',
        visibility: 'public'
      });
      setNewPost('');
      setShowPostForm(false);
      loadPosts();
    } catch (error) {
      console.error('Failed to create post:', error);
    }
  };

  return (
    <div className="activities-page">
      <div className="topbar">
        <div className="topbar-left">
          <div className="avatar-circle" />
          <div className="welcome-block">
            <p className="welcome-label">Welcome</p>
            <p className="welcome-name">
              {user?.username || user?.email?.split('@')[0] || 'Gamer'}
            </p>
          </div>
        </div>

        <div className="topbar-center">
          <button className="top-tab" onClick={() => navigate('/profile')}>
            Profile
          </button>
          <button className="top-tab" onClick={() => navigate('/gamer-home')}>
            Home
          </button>
          <button className="top-tab active" onClick={() => navigate('/activities')}>
            Activities
          </button>
        </div>

        <div className="topbar-right">
          <Link to="/gamer-home">
            <img src={logo} alt="Gamelink logo" />
          </Link>
        </div>
      </div>

      <div className="page-title-row">
        <h1>ACTIVITIES</h1>
        <div className="title-line" />
      </div>

      <div className="activities-grid">
        <div className="activities-card left-card">
          <div className="card-header">
            <span>Posts</span>
            <button className="icon-button" type="button" onClick={() => setShowPostForm(true)}>
              +
            </button>
          </div>

          <div className="upload-card">
            <div className="upload-placeholder">Upload media</div>
            {showPostForm ? (
              <>
                <textarea
                  value={newPost}
                  onChange={(e) => setNewPost(e.target.value)}
                  placeholder="Comment"
                />
                <div className="buttons-row">
                  <button className="activity-button primary" type="button" onClick={handleCreatePost}>
                    Upload
                  </button>
                  <button className="activity-button secondary" type="button" onClick={() => setShowPostForm(false)}>
                    Cancel
                  </button>
                </div>
              </>
            ) : (
              <div className="upload-hint">Click the + icon to upload</div>
            )}
          </div>

          <div className="posts-list">
            {posts.length > 0 ? (
              posts.map((post) => (
                <div key={post.id} className="post-card">
                  <h3>{post.username}</h3>
                  <p>{post.content}</p>
                  <div className="post-actions">
                    <button type="button">👍 {post.likes_count}</button>
                    <button type="button">💬 {post.comments_count}</button>
                  </div>
                </div>
              ))
            ) : (
              <div className="empty-state">No recent posts yet</div>
            )}
          </div>
        </div>

        <div className="activities-card right-card">
          <div className="card-header">
            <span>Activity Stats</span>
          </div>
          <div className="stats-list">
            {[
              'Account active duration:',
              'Total Take Ons:',
              'Greatest Rival:',
              'Take Ons won:',
              'Take Ons lost:',
              'Tournaments won:',
              'Tournaments lost:',
              'Tournaments hosted:',
              'Account status type:',
              'eSports teams signed into:',
              'Duration as signed gamer:',
              'Duration as free agent:'
            ].map((line) => (
              <div key={line} className="stats-item">
                <p>{line}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
